<?php
require __DIR__ . '/_bootstrap.php';global $db;$uid=api_require_user();zv2_refresh($uid);$h=$db->query("SELECT buildings,ressis FROM strongholds WHERE userid=$uid LIMIT 1");if(!$h||!$h->num_rows)json_err('no_stronghold','Stronghold not found.',404);$hold=$h->fetch_assoc();$levels=pipe_nums($hold['buildings']);$res=pipe_nums($hold['ressis']);$busy=(bool)zv2_active_builds($uid);$list=[];$q=$db->query("SELECT id,name,description FROM facilities WHERE id<>17 ORDER BY id");
while($q&&($f=$q->fetch_assoc())){$id=(int)$f['id'];if((int)($levels[$id]??0)>0)continue;$cost=[];$affordable=true;$cr=$db->query("SELECT water,food,wood,metal,petrol FROM facility_costs WHERE facility_id=$id AND level=1 LIMIT 1");if(!$cr||!$cr->num_rows)continue;$c=$cr->fetch_assoc();foreach(['water','food','wood','metal','petrol']as$i=>$key){$need=(int)$c[$key];if(!$need)continue;$owned=(int)floor($res[$i]??0);$enough=$owned>=$need;if(!$enough)$affordable=false;$cost[]=['res'=>$key,'amount'=>$need,'owned'=>$owned,'enough'=>$enough];}$list[]=['type'=>$id,'name'=>$f['name'],'description'=>$f['description'],'cost'=>$cost,'canBuild'=>$affordable&&!$busy,'reason'=>$busy?'Another construction project is active.':(!$affordable?'Missing resources.':'')];}
json_out(['ok'=>true,'grid'=>['w'=>ZV2_GRID_W,'h'=>ZV2_GRID_H],'facilities'=>$list]);
